#| One Newton update for sqrt(a).
#: x  the current estimate
#: a  the number whose root we want
def newton_sqrt_step(x, a) {
    #: fx  the residual x^2 - a; zero at the answer
    fx = x * x - a
    return x - fx / (2.0 * x)
}

