def kahan_sum(n, val) {
    s = 0.0
    comp = 0.0
    for i to n {
        y = val - comp
        t = s + y
        comp = (t - s) - y
        s = t
    }
    return s
}
show kahan_sum(1000000.0, 0.1) - 100000.0

def fib_rec(n) {
    if n < 1.5 {
        return n
    }
    return fib_rec(n - 1.0) + fib_rec(n - 2.0)
}
def fib_loop(n) {
    a = 0.0
    b = 1.0
    for i to n {
        t = a + b
        a = b
        b = t
    }
    return a
}
