def target(x) {
    return x * x - 2.0
}
def left(f, a, b) {
    return f(a)
}
def right(f, a, b) {
    return f(b)
}
def spread(ms, f, a, b) {
    lo = apply(ms[0], f, a, b)
    hi = lo
    for i to len(ms) {
        v = apply(ms[i], f, a, b)
        lo = min(lo, v)
        hi = max(hi, v)
    }
    return hi - lo
}
show spread([left, right], target, 0.0, 3.0)

