def collatz_len(n) {
    steps = 0.0
    while n > 1.5 {
        if mod(n, 2.0) < 0.5 {
            n = n / 2.0
        } else {
            n = 3.0 * n + 1.0
        }
        steps += 1.0
    }
    return steps
}
show collatz_len(27.0)

